using System.Diagnostics;

var app = WebApplication.Create(args);

app.Use(async (ctx, next) =>                 // timing middleware
{
    var sw = Stopwatch.StartNew();
    ctx.Response.OnStarting(() =>
    {
        ctx.Response.Headers["X-Elapsed-Ms"] = sw.ElapsedMilliseconds.ToString();
        return Task.CompletedTask;
    });
    await next(ctx);
});

app.Use(async (ctx, next) =>                 // short-circuit middleware
{
    if (!ctx.Request.Headers.ContainsKey("X-Block")) { await next(ctx); return; }
    ctx.Response.StatusCode = 403;           // next is never called
    await ctx.Response.WriteAsync("blocked");
});
app.MapGet("/", () => "hello");
app.Run();
// curl -i /             -> 200 hello, header X-Elapsed-Ms: 0
// curl -H "X-Block: 1" / -> 403 blocked

