var builder = WebApplication.CreateBuilder(args);
builder.Services.AddDbContext<AppDb>(o => o.UseSqlite("Data Source=app.db"));
var app = builder.Build();
app.MapGet("/todos", async (AppDb db) =>
    await db.Todos.AsNoTracking()
        .Where(t => !t.Done).OrderBy(t => t.Id)
        .Select(t => new { t.Id, t.Title })      // only needed columns
        .ToListAsync());
app.MapPost("/todos", async (AppDb db, Todo todo) =>
{
    db.Todos.Add(todo);
    await db.SaveChangesAsync();                 // INSERT, Id filled in
    return TypedResults.Created($"/todos/{todo.Id}", todo);
});
app.MapPost("/todos/complete-all", async (AppDb db) =>   // one UPDATE statement
    await db.Todos.ExecuteUpdateAsync(s => s.SetProperty(t => t.Done, true)));
app.Run();

