class EmailWorker(Channel<string> queue, IServiceScopeFactory scopes, ILogger<EmailWorker> log) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken) {
        await foreach (var to in queue.Reader.ReadAllAsync(stoppingToken))
        {
            try
            {   using var scope = scopes.CreateScope();   // scoped services per item
                await Task.Delay(100, stoppingToken);     // send the email here
                log.LogInformation("Sent email to {To}", to); }
            catch (Exception ex) when (ex is not OperationCanceledException)
            { log.LogError(ex, "Failed to email {To}", to); }
        }
    }
}

